        assert_eq!(read(r(format!("offline/loss-{name}/stdout.log")))["zero_lost"],true);let attr=fs::read_to_string(r(format!("offline/events-{name}/stdout.log"))).unwrap();for item in[format!("{event}:u"),"199".into(),"freq: 1".into(),"CPU".into(),"TIME".into()]{assert!(attr.contains(&item));}
